def __add__(self, other: Monomial) -> Monomial:
    """Add two monomials together.

    Args:
        other: Another Monomial to add.

    Returns:
        The resulting Monomial.

    Raises:
        ValueError: If monomials have different variables.
    """
    if not isinstance(other, Monomial):
        raise ValueError("Can only add monomials.")
    if self.variables == other.variables:
        mono = {i: self.variables[i] for i in self.variables}
        return Monomial(
            mono, Monomial._rationalize_if_possible(self.coeff + other.coeff)
        ).clean()
    raise ValueError(
        f"Cannot add {str(other)} to {self.__str__()} "
        "because they don't have same variables."
    )

def __sub__(self, other: Monomial) -> Monomial:
    """Subtract two monomials.

    Args:
        other: Another Monomial to subtract.

    Returns:
        The resulting Monomial.

    Raises:
        ValueError: If monomials have different variables.
    """
    negated = Monomial({i: -v for i, v in other.variables.items()},
                       Monomial._rationalize_if_possible(-1)).clean() * other
    return self.__add__(negated)

def __mul__(self, other: Monomial | int | float | Fraction) -> Monomial:
    """Multiply this monomial by another.

    Args:
        other: Another Monomial, int, float, or Fraction to multiply by.

    Returns:
        The resulting Monomial.
    """
    if isinstance(other, (int, float, Fraction)):
        mono = {i: self.variables[i] for i in self.variables}
        return Monomial(
            mono, Monomial._rationalize_if_possible(self.coeff * other)
        ).clean()

    if not isinstance(other, Monomial):
        raise ValueError("Can only multiply monomials, ints, floats, or Fractions.")
    else:
        mono = {i: self.variables[i] for i in self.variables}
        for i in other.variables:
            if i in mono:
                mono[i] += other.variables[i]
            else:
                mono[i] = other.variables[i]

        temp = dict()
        for k in mono:
            if mono[k] != 0:
                temp[k] = mono[k]

        return Monomial(
            temp, Monomial._rationalize_if_possible(self.coeff * other.coeff)
        ).clean()

def __truediv__(self, other: Monomial | int | float | Fraction) -> Monomial:
    """Divide this monomial by another.

    Args:
        other: Another Monomial, int, float, or Fraction divisor.

    Returns:
        The resulting Monomial.

    Raises:
        ValueError: If dividing by zero.
    """
    if isinstance(other, (int, float, Fraction)):
        mono = {i: self.variables[i] for i in self.variables}
        if other == 0:
            raise ValueError("Cannot divide by 0.")
        return Monomial(
            mono, Monomial._rationalize_if_possible(self.coeff / other)
        ).clean()

    o = other.inverse()
    return self.__mul__(o)

def __floordiv__(self, other: Monomial | int | float | Fraction) -> Monomial:
    """Floor division (same as true division for monomials)."""
    return self.__truediv__(other)

def __hash__(self) -> int:
    """Hash based on the underlying variables.

    Returns:
        An integer hash value.
    """
    arr = []
    for i in sorted(self.variables):
        if self.variables[i] > 0:
            for _ in range(self.variables[i]):
                arr.append(i)
    return hash(tuple(arr))
